"""Build FEATURE_LEDGER.json (implemented / exercised / environment / remaining limits per capability) from the final journeys record."""
import json, sys
from pathlib import Path
A = Path(sys.argv[1]); J = json.load(open(A / 'journeys' / 'journeys-mission.json')); res = {r['journey']: r for r in J['results']}
def ex(*ns):
    rows = [res.get(n) for n in ns if res.get(n)]
    return {'journeys': list(ns), 'statuses': [r['status'] for r in rows], 'exercised': bool(rows) and all(r['status'] == 'passed' for r in rows)}
